window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-da5a8e4e84aab3f0"]={"versions": [{"id": "FIG-da5a8e4e84aab3f0", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Metamodell-Klassendiagramm (AUTOSAR Adaptive Platform, Manifest-Spezifikation).</li>\n<li><strong>Funktionale Einordnung:</strong> Definiert die Vererbungshierarchie der abstrakten Meta-Klasse <code>UploadableDeploymentElement</code> (TPS_MANI_01414, RS_MANI_00035). Sie bildet die normative Basis für alle ARXML-Modellelemente, die über den UCM-Mechanismus (Update and Configuration Management) via <code>SoftwarePackage</code> oder <code>VehiclePackage</code> auf eine Adaptive Machine ausgerollt, paketiert und aktiviert werden können.</li>\n<li><strong>Zweck:</strong> Typsichere Abgrenzung zwischen reinen Entwurfs- bzw. Typ-Artefakten (z. B. PortInterfaces, C++-Datentypen) und tatsächlich deploybaren Instanzierungs-, Konfigurations- und Mapping-Elementen eines Software-Clusters oder einer Machine.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Basis-Klassenhierarchie</p>\n<ul class=\"fig-list\">\n<li><code>ARElement</code> <em>(abstrakt)</em>: Wurzelklasse aller eigenständigen, paketierbaren AUTOSAR-Modellelemente im ARXML-Datenmodell.</li>\n<li><code>UploadablePackageElement</code> <em>(abstrakt, spezialisiert ARElement)</em>: Abstrakte Zwischenklasse für Elemente, die innerhalb von Deployment-Containern gekapselt werden dürfen.</li>\n<li><code>UploadableDeploymentElement</code> <em>(abstrakt, spezialisiert UploadablePackageElement)</em>: Zentraler Integrationsknoten für alle deploybaren Manifest-Bestandteile.</li>\n</ul>\n<p class=\"fig-p\">#### Spezialisierungen (Subklassen von <code>UploadableDeploymentElement</code>)</p>\n<p class=\"fig-p\">Die abgeleiteten Klassen gliedern sich funktional in folgende Domänen:</p>\n<ol class=\"fig-list\">\n<li><strong>Packaging, Execution & Machine Architecture:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>SoftwarePackage</code> / <code>VehiclePackage</code>: Top-Level-Container für OTA- bzw. Werkstatt-Deployments.</li>\n<li><code>SoftwareCluster</code>: Logische Deployment- und Update-Einheit auf einer Machine.</li>\n<li><code>Machine</code> <em>(spezialisiert <code>AtpStructureElement</code>)</em>: Repräsentation des physischen/virtuellen Compute-Nodes.</li>\n<li><code>StartupConfig</code>: Startparameter, Umgebungsüberwachung und Ressourceneinstellungen für Prozesse.</li>\n<li><code>AbstractExecutionContext</code> <em>(spezialisiert <code>AtpClassifier</code>)</em> / <code>ProcessExecutionError</code>: Fehler- und Kontextdefinitionen für Prozesse.</li>\n<li><code>ProcessToMachineMappingSet</code>: Zuweisung von Prozessen zur ausführenden Machine.</li>\n<li><code>UploadableExclusivePackageElement</code>: Elemente mit exklusiver Paketierungsbindung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Security & Identity/Access Management (IAM):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Grant</code> & <code>AbstractIamRemoteSubject</code>: Zugriffssteuerungs- und Rechtevergabe-Regeln im IAM-Framework.</li>\n<li><code>AdaptiveFirewallToPortPrototypeMapping</code>: Firewall-Regelwerksbindung an Kommunikations-Ports.</li>\n<li><code>CryptoKeySlotToPortPrototypeMapping</code>, <code>CryptoCertificateToPortPrototypeMapping</code>, <code>CryptoProviderToPortPrototypeMapping</code>: Anbindung kryptografischer Schlüssel, Zertifikate und Treiber an Port-Schnittstellen.</li>\n<li><code>SecurityEventMapping</code>: Zuordnung von sicherheitsrelevanten Vorfällen (z. B. für IVSM/IDS).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Platform Health Management (PHM):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>PlatformHealthManagementContribution</code>: Definition lokaler Überwachungsregeln (Alive-, Deadline-, Logical-Supervision).</li>\n<li><code>PhmContributionToMachineMapping</code>: Bindung der PHM-Regelsätze an eine konkrete Machine.</li>\n<li><code>RecoveryNotification</code>: Signalisierung von Wiederherstellungsmaßnahmen.</li>\n<li><code>RecoveryNotificationToPPortPrototypeMapping</code>: Zuweisung von Recovery-Ereignissen an PPorts.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Logging, Tracing & Time Synchronization:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>DltLogSink</code>: Konfiguration von Log-Sinks (z. B. Datei, Socket, Console) für das Diagnostic Log and Trace-Subsystem.</li>\n<li><code>DltApplicationToProcessMapping</code> / <code>DltLogSinkToPortPrototypeMapping</code>: Zuordnung von DLT-Applikationskontexten und -Sinks zu Prozessen/Ports.</li>\n<li><code>TimeSyncPortPrototypeToTimeBaseMapping</code>: Bindung lokaler Zeitbasis-Instanzen (gPTP/IEEE 802.1AS) an Software-Ports.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Netzwerk & Inter-Cluster-Kommunikation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>RawDataStreamDeployment</code> / <code>RawDataStreamMapping</code>: Konfiguration unstrukturierter Streaming-Schnittstellen.</li>\n<li><code>NmHandleToFunctionGroupStateMapping</code>: Netzwerkmanagement-Kopplung an Funktionsgruppenzustände des Execution Management.</li>\n<li><code>NetworkHandlePortMapping</code>: Zuordnung von physischen/logischen Netzwerk-Handles zu Ports.</li>\n<li><code>FunctionalClusterInteractsWithFunctionalClusterMapping</code>: Spezifikation von Interaktionsbeziehungen zwischen funktionalen Clustern.</li>\n<li><code>SoftwareClusterDiagnosticDeploymentProps</code>: Diagnosespezifische Bereitstellungseigenschaften eines Software-Clusters.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm existiert kein Laufzeit-Callflow; das Modell determiniert jedoch den statischen Validierungs- und Bereitstellungszyklus im <strong>UCM-Workflow</strong>:</p>\n<ol class=\"fig-list\">\n<li><strong>Paketerstellung (Design- & Build-Time):</strong> Der Manifest-Generator instanziiert konkrete Subklassen von <code>UploadableDeploymentElement</code> und bettet sie in ein <code>SoftwarePackage</code> ein.</li>\n<li><strong>Transfer & Extraktion (UCM Transfer Phase):</strong> UCM empfängt das Paket und liest die Manifeste aus. Elemente, die nicht von <code>UploadableDeploymentElement</code> erben, führen zur Zurückweisung des Pakets.</li>\n<li><strong>Validierung & Resolving (UCM Processing Phase):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>UCM und Plattformdienste (Execution Management, IAM, PHM) lösen Abhängigkeiten auf: Zuweisung von <code>StartupConfig</code> an Prozesse, Zertifikatsbindung (<code>Crypto*Mapping</code>) und Health-Regeln (<code>PlatformHealthManagementContribution</code>).</li>\n<li>Prüfung von <code>NmHandleToFunctionGroupStateMapping</code> und <code>Machine</code>-Integrität.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktivierung (Activation Phase):</strong> Execution Management instanziiert Prozesse gemäß den Mappings; Plattform-Dämonen (Crypto Daemon, DLT, PHM) binden die deklarierten Ports basierend auf den aufgelösten Mappings.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Generierung & Tool-Chains:</strong> ARXML-Generatoren müssen sicherstellen, dass alle zur Laufzeit aktualisierbaren Artefakte strikt als Subklassen von <code>UploadableDeploymentElement</code> modelliert sind. Entwurfszeit-Elemente (wie abstrakte Interfaces) dürfen nicht direkt als Deployment-Einheiten deklariert werden.</li>\n<li><strong>Entkopplung durch Mappings:</strong> Funktionale Cluster (Crypto, PHM, DLT, Firewall) greifen niemals direkt auf Prozess-Binaries zu, sondern werden ausschließlich über die typisierten <code>*ToPortPrototypeMapping</code>-Elemente entkoppelt an Service- und Anwendungshäfen gebunden.</li>\n<li><strong>UCM-Granularität:</strong> Die Definition von <code>SoftwareCluster</code> und <code>SoftwarePackage</code> als <code>UploadableDeploymentElement</code> erzwingt, dass ein Software-Cluster modular aktualisiert werden kann, ohne dass die gesamte Machine neu geflasht werden muss.</li>\n<li><strong>Sicherheits- und Zugriffsrichtlinien:</strong> <code>Grant</code> und <code>AbstractIamRemoteSubject</code> erlauben eine feingranulare Vergabe von IPC- und Service-Rechten pro deploytem Element; fehlende Mappings führen zum deterministischen Zugriffsabbruch (Access Denied) durch das adaptive IAM-Subsystem.</li>\n</ul>"}, {"id": "FIG-73898051c375ba44", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Metamodell-Klassendiagramm (AUTOSAR Adaptive Platform, Manifest-Spezifikation).</li>\n<li><strong>Funktionale Einordnung:</strong> Definiert die Vererbungshierarchie der abstrakten Meta-Klasse <code>UploadableDeploymentElement</code> (TPS_MANI_01414, RS_MANI_00035). Sie bildet die normative Basis für alle ARXML-Modellelemente, die über den UCM-Mechanismus (Update and Configuration Management) via <code>SoftwarePackage</code> oder <code>VehiclePackage</code> auf eine Adaptive Machine ausgerollt, paketiert und aktiviert werden können.</li>\n<li><strong>Zweck:</strong> Typsichere Abgrenzung zwischen reinen Entwurfs- bzw. Typ-Artefakten (z. B. PortInterfaces, C++-Datentypen) und tatsächlich deploybaren Instanzierungs-, Konfigurations- und Mapping-Elementen eines Software-Clusters oder einer Machine.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Basis-Klassenhierarchie</p>\n<ul class=\"fig-list\">\n<li><code>ARElement</code> <em>(abstrakt)</em>: Wurzelklasse aller eigenständigen, paketierbaren AUTOSAR-Modellelemente im ARXML-Datenmodell.</li>\n<li><code>UploadablePackageElement</code> <em>(abstrakt, spezialisiert ARElement)</em>: Abstrakte Zwischenklasse für Elemente, die innerhalb von Deployment-Containern gekapselt werden dürfen.</li>\n<li><code>UploadableDeploymentElement</code> <em>(abstrakt, spezialisiert UploadablePackageElement)</em>: Zentraler Integrationsknoten für alle deploybaren Manifest-Bestandteile.</li>\n</ul>\n<p class=\"fig-p\">#### Spezialisierungen (Subklassen von <code>UploadableDeploymentElement</code>)</p>\n<p class=\"fig-p\">Die abgeleiteten Klassen gliedern sich funktional in folgende Domänen:</p>\n<ol class=\"fig-list\">\n<li><strong>Packaging, Execution & Machine Architecture:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>SoftwarePackage</code> / <code>VehiclePackage</code>: Top-Level-Container für OTA- bzw. Werkstatt-Deployments.</li>\n<li><code>SoftwareCluster</code>: Logische Deployment- und Update-Einheit auf einer Machine.</li>\n<li><code>Machine</code> <em>(spezialisiert <code>AtpStructureElement</code>)</em>: Repräsentation des physischen/virtuellen Compute-Nodes.</li>\n<li><code>StartupConfig</code>: Startparameter, Umgebungsüberwachung und Ressourceneinstellungen für Prozesse.</li>\n<li><code>AbstractExecutionContext</code> <em>(spezialisiert <code>AtpClassifier</code>)</em> / <code>ProcessExecutionError</code>: Fehler- und Kontextdefinitionen für Prozesse.</li>\n<li><code>ProcessToMachineMappingSet</code>: Zuweisung von Prozessen zur ausführenden Machine.</li>\n<li><code>FunctionGroupPortMapping</code>: Bindung von Function Groups an PortPrototypes.</li>\n<li><code>UploadableExclusivePackageElement</code>: Elemente mit exklusiver Paketierungsbindung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Security & Identity/Access Management (IAM):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Grant</code> & <code>AbstractIamRemoteSubject</code>: Zugriffssteuerungs- und Rechtevergabe-Regeln im IAM-Framework.</li>\n<li><code>AdaptiveFirewallToPortPrototypeMapping</code>: Firewall-Regelwerksbindung an Kommunikations-Ports.</li>\n<li><code>AbstractCryptoKeySlotToPortPrototypeMapping</code> <em>(abstrakt)</em>: Abstrakte Basisklasse zur Bindung von Key Slots an PortPrototypes.</li>\n<li><code>CryptoKeySlotToPortPrototypeMapping</code> <em>(spezialisiert <code>AbstractCryptoKeySlotToPortPrototypeMapping</code>)</em>: Konkrete Zuordnung von Crypto Key Slots zu PortPrototypes.</li>\n<li><code>CryptoCertificateToPortPrototypeMapping</code>, <code>CryptoProviderToPortPrototypeMapping</code>: Anbindung kryptografischer Zertifikate und Provider an Port-Schnittstellen.</li>\n<li><code>SecurityEventMapping</code>: Zuordnung von sicherheitsrelevanten Vorfällen (z. B. für IVSM/IDS).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Intrusion Detection System Manager (IDSM):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>IdsmQualifiedEventReceiverMapping</code>: Zuordnung qualifizierter Security-Event-Empfänger.</li>\n<li><code>IdsmTimestampProviderMapping</code>: Anbindung von Timestamp-Providern an das IDSM-Subsystem.</li>\n<li><code>IdsmContextProviderMapping</code>: Bereitstellung von Kontextinformationen für Security-Events.</li>\n<li><code>IdsmReportingModeProviderMapping</code>: Konfiguration des Reporting-Modus für IDSM-Ereignisse.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Platform Health Management (PHM):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>PlatformHealthManagementContribution</code>: Definition lokaler Überwachungsregeln (Alive-, Deadline-, Logical-Supervision).</li>\n<li><code>PhmContributionToMachineMapping</code>: Bindung der PHM-Regelsätze an eine konkrete Machine.</li>\n<li><code>RecoveryNotification</code>: Signalisierung von Wiederherstellungsmaßnahmen.</li>\n<li><code>RecoveryNotificationToPPortPrototypeMapping</code>: Zuweisung von Recovery-Ereignissen an PPorts.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Logging, Tracing & Time Synchronization:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>DltLogSink</code>: Konfiguration von Log-Sinks (z. B. Datei, Socket, Console) für das Diagnostic Log and Trace-Subsystem.</li>\n<li><code>DltApplicationToProcessMapping</code> / <code>DltLogSinkToPortPrototypeMapping</code>: Zuordnung von DLT-Applikationskontexten zu Prozessen bzw. Port-Prototypes zu Log-Sinks.</li>\n<li><code>TimeSyncPortPrototypeToTimeBaseMapping</code>: Bindung von synchronisierten Port-Prototypes an interne Time Bases.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Communication, Diagnostics & Network Management:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>RawDataStreamDeployment</code> / <code>RawDataStreamMapping</code>: Konfiguration und Mapping von Streaming-Schnittstellen für Rohdaten.</li>\n<li><code>SoftwareClusterDiagnosticDeploymentProps</code>: Diagnose-Deployment-Eigenschaften eines SoftwareClusters.</li>\n<li><code>NmHandleToFunctionGroupStateMapping</code>: Zuordnung von Network Management Handles zu Function Group States.</li>\n<li><code>NetworkHandlePortMapping</code>: Zuordnung von Network Handles zu Port-Schnittstellen.</li>\n<li><code>FunctionalClusterInteractsWithFunctionalClusterMapping</code>: Spezifikation der Interaktion zwischen Functional Clustern.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm existiert kein Laufzeit-Callflow; das Modell determiniert jedoch den statischen Validierungs- und Bereitstellungszyklus im <strong>UCM-Workflow</strong>:</p>\n<ol class=\"fig-list\">\n<li><strong>Paketerstellung (Design- & Build-Time):</strong> Der Manifest-Generator instanziiert konkrete Subklassen von <code>UploadableDeploymentElement</code> und bettet sie in ein <code>SoftwarePackage</code> ein.</li>\n<li><strong>Transfer & Extraktion (UCM Transfer Phase):</strong> UCM empfängt das Paket und liest die Manifeste aus. Elemente, die nicht von <code>UploadableDeploymentElement</code> erben, führen zur Zurückweisung des Pakets.</li>\n<li><strong>Validierung & Resolving (UCM Processing Phase):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>UCM und Plattformdienste (Execution Management, IAM, PHM) lösen Abhängigkeiten auf: Zuweisung von <code>StartupConfig</code> an Prozesse, Zertifikatsbindung (<code>Crypto*Mapping</code>) und Health-Regeln (<code>PlatformHealthManagementContribution</code>).</li>\n<li>Prüfung von <code>NmHandleToFunctionGroupStateMapping</code> und <code>Machine</code>-Integrität.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktivierung (Activation Phase):</strong> Execution Management instanziiert Prozesse gemäß den Mappings; Plattform-Dämonen (Crypto Daemon, DLT, PHM) binden die deklarierten Ports basierend auf den aufgelösten Mappings.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Generierung & Tool-Chains:</strong> ARXML-Generatoren müssen sicherstellen, dass alle zur Laufzeit aktualisierbaren Artefakte strikt als Subklassen von <code>UploadableDeploymentElement</code> modelliert sind. Entwurfszeit-Elemente (wie abstrakte Interfaces) dürfen nicht direkt als Deployment-Einheiten deklariert werden.</li>\n<li><strong>Entkopplung durch Mappings:</strong> Funktionale Cluster (Crypto, PHM, DLT, Firewall) greifen niemals direkt auf Prozess-Binaries zu, sondern werden ausschließlich über die typisierten <code>*ToPortPrototypeMapping</code>-Elemente entkoppelt an Service- und Anwendungshäfen gebunden.</li>\n<li><strong>UCM-Granularität:</strong> Die Definition von <code>SoftwareCluster</code> und <code>SoftwarePackage</code> als <code>UploadableDeploymentElement</code> erzwingt, dass ein Software-Cluster modular aktualisiert werden kann, ohne dass die gesamte Machine neu geflasht werden muss.</li>\n<li><strong>Sicherheits- und Zugriffsrichtlinien:</strong> <code>Grant</code> und <code>AbstractIamRemoteSubject</code> erlauben eine feingranulare Vergabe von IPC- und Service-Rechten pro deploytem Element; fehlende Mappings führen zum deterministischen Zugriffsabbruch (Access Denied) durch das adaptive IAM-Subsystem.</li>\n</ul>"}, {"id": "FIG-5611207a9fd328a7", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Metamodell-Klassendiagramm (AUTOSAR Adaptive Platform, Manifest-Spezifikation).</li>\n<li><strong>Funktionale Einordnung:</strong> Definiert die Vererbungshierarchie der abstrakten Meta-Klasse <code>UploadableDeploymentElement</code> (TPS_MANI_01414, RS_MANI_00035). Sie bildet die normative Basis für alle ARXML-Modellelemente, die über den UCM-Mechanismus (Update and Configuration Management) via <code>SoftwarePackage</code> oder <code>VehiclePackage</code> auf eine Adaptive Machine ausgerollt, paketiert und aktiviert werden können.</li>\n<li><strong>Zweck:</strong> Typsichere Abgrenzung zwischen reinen Entwurfs- bzw. Typ-Artefakten (z. B. PortInterfaces, C++-Datentypen) und tatsächlich deploybaren Instanzierungs-, Konfigurations- und Mapping-Elementen eines Software-Clusters oder einer Machine.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Basis-Klassenhierarchie</p>\n<ul class=\"fig-list\">\n<li><code>ARElement</code> <em>(abstrakt)</em>: Wurzelklasse aller eigenständigen, paketierbaren AUTOSAR-Modellelemente im ARXML-Datenmodell.</li>\n<li><code>UploadablePackageElement</code> <em>(abstrakt, spezialisiert ARElement)</em>: Abstrakte Zwischenklasse für Elemente, die innerhalb von Deployment-Containern gekapselt werden dürfen.</li>\n<li><code>UploadableDeploymentElement</code> <em>(abstrakt, spezialisiert UploadablePackageElement)</em>: Zentraler Integrationsknoten für alle deploybaren Manifest-Bestandteile.</li>\n</ul>\n<p class=\"fig-p\">#### Spezialisierungen (Subklassen von <code>UploadableDeploymentElement</code>)</p>\n<p class=\"fig-p\">Die abgeleiteten Klassen gliedern sich funktional in folgende Domänen:</p>\n<ol class=\"fig-list\">\n<li><strong>Packaging, Execution & Machine Architecture:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>SoftwarePackage</code> / <code>VehiclePackage</code>: Top-Level-Container für OTA- bzw. Werkstatt-Deployments.</li>\n<li><code>SoftwareCluster</code>: Logische Deployment- und Update-Einheit auf einer Machine.</li>\n<li><code>Machine</code> <em>(spezialisiert <code>AtpStructureElement</code>)</em>: Repräsentation des physischen/virtuellen Compute-Nodes.</li>\n<li><code>StartupConfig</code>: Startparameter, Umgebungsüberwachung und Ressourceneinstellungen für Prozesse.</li>\n<li><code>AbstractExecutionContext</code> <em>(spezialisiert <code>AtpClassifier</code>)</em>: Kontextdefinitionen für Prozesse.</li>\n<li><code>ProcessToMachineMappingSet</code>: Zuweisung von Prozessen zur ausführenden Machine.</li>\n<li><code>FunctionGroupPortMapping</code>: Bindung von Function Groups an PortPrototypes.</li>\n<li><code>UploadableExclusivePackageElement</code>: Elemente mit exklusiver Paketierungsbindung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Security & Identity/Access Management (IAM):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Grant</code> & <code>AbstractIamRemoteSubject</code>: Zugriffssteuerungs- und Rechtevergabe-Regeln im IAM-Framework.</li>\n<li><code>AdaptiveFirewallToPortPrototypeMapping</code>: Firewall-Regelwerksbindung an Kommunikations-Ports.</li>\n<li><code>AbstractCryptoKeySlotToPortPrototypeMapping</code> <em>(abstrakt)</em>: Abstrakte Basisklasse zur Bindung von Key Slots an PortPrototypes.</li>\n<li><code>CryptoKeySlotToPortPrototypeMapping</code> <em>(spezialisiert <code>AbstractCryptoKeySlotToPortPrototypeMapping</code>)</em>: Konkrete Zuordnung von Crypto Key Slots zu PortPrototypes.</li>\n<li><code>CryptoCertificateToPortPrototypeMapping</code>, <code>CryptoProviderToPortPrototypeMapping</code>: Anbindung kryptografischer Zertifikate und Provider an Port-Schnittstellen.</li>\n<li><code>SecurityEventMapping</code>: Zuordnung von sicherheitsrelevanten Vorfällen (z. B. für IVSM/IDS).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Intrusion Detection System Manager (IDSM):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>IdsmQualifiedEventReceiverMapping</code>: Zuordnung qualifizierter Security-Event-Empfänger.</li>\n<li><code>IdsmTimestampProviderMapping</code>: Anbindung von Timestamp-Providern an das IDSM-Subsystem.</li>\n<li><code>IdsmContextProviderMapping</code>: Bereitstellung von Kontextinformationen für Security-Events.</li>\n<li><code>IdsmReportingModeProviderMapping</code>: Konfiguration des Reporting-Modus für IDSM-Ereignisse.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Platform Health Management (PHM):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>PlatformHealthManagementContribution</code>: Definition lokaler Überwachungsregeln (Alive-, Deadline-, Logical-Supervision).</li>\n<li><code>PhmContributionToMachineMapping</code>: Bindung der PHM-Regelsätze an eine konkrete Machine.</li>\n<li><code>RecoveryNotification</code>: Signalisierung von Wiederherstellungsmaßnahmen.</li>\n<li><code>RecoveryNotificationToPPortPrototypeMapping</code>: Zuweisung von Recovery-Ereignissen an PPorts.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Logging, Tracing & Time Synchronization:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>DltLogSink</code>: Konfiguration von Log-Sinks (z. B. Datei, Socket, Console) für das Diagnostic Log and Trace-Subsystem.</li>\n<li><code>DltApplicationToProcessMapping</code> / <code>DltLogSinkToPortPrototypeMapping</code>: Zuordnung von DLT-Applikationskontexten zu Prozessen bzw. Port-Prototypes zu Log-Sinks.</li>\n<li><code>TimeSyncPortPrototypeToTimeBaseMapping</code>: Bindung von synchronisierten Port-Prototypes an interne Time Bases.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Communication, Diagnostics & Network Management:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>RawDataStreamDeployment</code> / <code>RawDataStreamMapping</code>: Konfiguration und Mapping von Streaming-Schnittstellen für Rohdaten.</li>\n<li><code>SoftwareClusterDiagnosticDeploymentProps</code>: Diagnose-Deployment-Eigenschaften eines SoftwareClusters.</li>\n<li><code>NmHandleToFunctionGroupStateMapping</code>: Zuordnung von Network Management Handles zu Function Group States.</li>\n<li><code>NetworkHandlePortMapping</code>: Zuordnung von Network Handles zu Port-Schnittstellen.</li>\n<li><code>FunctionalClusterInteractsWithFunctionalClusterMapping</code>: Spezifikation der Interaktion zwischen Functional Clustern.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm existiert kein Laufzeit-Callflow; das Modell determiniert jedoch den statischen Validierungs- und Bereitstellungszyklus im <strong>UCM-Workflow</strong>:</p>\n<ol class=\"fig-list\">\n<li><strong>Paketerstellung (Design- & Build-Time):</strong> Der Manifest-Generator instanziiert konkrete Subklassen von <code>UploadableDeploymentElement</code> und bettet sie in ein <code>SoftwarePackage</code> ein.</li>\n<li><strong>Transfer & Extraktion (UCM Transfer Phase):</strong> UCM empfängt das Paket und liest die Manifeste aus. Elemente, die nicht von <code>UploadableDeploymentElement</code> erben, führen zur Zurückweisung des Pakets.</li>\n<li><strong>Validierung & Resolving (UCM Processing Phase):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>UCM und Plattformdienste (Execution Management, IAM, PHM) lösen Abhängigkeiten auf: Zuweisung von <code>StartupConfig</code> an Prozesse, Zertifikatsbindung (<code>Crypto*Mapping</code>) und Health-Regeln (<code>PlatformHealthManagementContribution</code>).</li>\n<li>Prüfung von <code>NmHandleToFunctionGroupStateMapping</code> und <code>Machine</code>-Integrität.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aktivierung (Activation Phase):</strong> Execution Management instanziiert Prozesse gemäß den Mappings; Plattform-Dämonen (Crypto Daemon, DLT, PHM) binden die deklarierten Ports basierend auf den aufgelösten Mappings.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Generierung & Tool-Chains:</strong> ARXML-Generatoren müssen sicherstellen, dass alle zur Laufzeit aktualisierbaren Artefakte strikt als Subklassen von <code>UploadableDeploymentElement</code> modelliert sind. Entwurfszeit-Elemente (wie abstrakte Interfaces) dürfen nicht direkt als Deployment-Einheiten deklariert werden.</li>\n<li><strong>Entkopplung durch Mappings:</strong> Funktionale Cluster (Crypto, PHM, DLT, Firewall) greifen niemals direkt auf Prozess-Binaries zu, sondern werden ausschließlich über die typisierten <code>*ToPortPrototypeMapping</code>-Elemente entkoppelt an Service- und Anwendungshäfen gebunden.</li>\n<li><strong>UCM-Granularität:</strong> Die Definition von <code>SoftwareCluster</code> und <code>SoftwarePackage</code> als <code>UploadableDeploymentElement</code> erzwingt, dass ein Software-Cluster modular aktualisiert werden kann, ohne dass die gesamte Machine neu geflasht werden muss.</li>\n<li><strong>Sicherheits- und Zugriffsrichtlinien:</strong> <code>Grant</code> und <code>AbstractIamRemoteSubject</code> erlauben eine feingranulare Vergabe von IPC- und Service-Rechten pro deploytem Element; fehlende Mappings führen zum deterministischen Zugriffsabbruch (Access Denied) durch das adaptive IAM-Subsystem.</li>\n</ul>"}], "trans": [{"from": "FIG-da5a8e4e84aab3f0", "to": "FIG-73898051c375ba44", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>AbstractCryptoKeySlotToPortPrototypeMapping</code>: Neue abstrakte Subklasse von <code>UploadableDeploymentElement</code> eingeführt.</li>\n<li><code>CryptoKeySlotToPortPrototypeMapping</code>: Vererbungsbeziehung geändert; spezialisiert nun <code>AbstractCryptoKeySlotToPortPrototypeMapping</code> statt direkt <code>UploadableDeploymentElement</code>.</li>\n<li><code>IdsmTimestampProviderMapping</code>: Neu als Subklasse von <code>UploadableDeploymentElement</code> hinzugefügt.</li>\n<li><code>IdsmContextProviderMapping</code>: Neu als Subklasse von <code>UploadableDeploymentElement</code> hinzugefügt.</li>\n<li><code>IdsmReportingModeProviderMapping</code>: Neu als Subklasse von <code>UploadableDeploymentElement</code> hinzugefügt.</li>\n<li><code>IdsmQualifiedEventReceiverMapping</code>: Neu als Subklasse von <code>UploadableDeploymentElement</code> hinzugefügt.</li>\n<li><code>FunctionGroupPortMapping</code>: Neu als Subklasse von <code>UploadableDeploymentElement</code> hinzugefügt.</li>\n<li>Layout: Positionen von <code>NetworkHandlePortMapping</code>, <code>TimeSyncPortPrototypeToTimeBaseMapping</code> und <code>FunctionalClusterInteractsWithFunctionalClusterMapping</code> neu angeordnet.</li>\n</ul>"}, {"from": "FIG-73898051c375ba44", "to": "FIG-5611207a9fd328a7", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>ProcessExecutionError</code>: Als Subklasse von <code>UploadableDeploymentElement</code> entfernt.</li>\n</ul>"}]};
